begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare360_pedagogical_assignments(id uuid primary key default gen_random_uuid(),school_id uuid not null,staff_id uuid,class_id uuid,section_id uuid,subject_id uuid,site_id uuid,academic_year_id uuid,assignment_type text not null,state text not null default 'draft',starts_at timestamptz,ends_at timestamptz,weekly_hours numeric(8,2) not null default 0,allocation_percent numeric(6,2),replacement_for_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_policy_catalog(id uuid primary key default gen_random_uuid(),school_id uuid,policy_key text not null,version integer not null default 1,label text not null,configuration jsonb not null default '{}',effective_from timestamptz,effective_to timestamptz,state text not null default 'active',created_at timestamptz not null default now(),unique(school_id,policy_key,version));
create table if not exists public.angelcare360_assignment_conflicts(id uuid primary key default gen_random_uuid(),school_id uuid not null,fingerprint text not null,category text not null,title text not null,detail text not null,consequence text,staff_id uuid,assignment_id uuid,class_id uuid,severity text not null default 'warning',state text not null default 'open',owner_label text,due_at timestamptz,recommended_action_key text,recommended_action_label text,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,fingerprint));
create table if not exists public.angelcare360_assignment_replacements(id uuid primary key default gen_random_uuid(),school_id uuid not null,source_assignment_id uuid,original_staff_id uuid,replacement_staff_id uuid,original_staff_label text,replacement_staff_label text,starts_at timestamptz,ends_at timestamptz,reason text,state text not null default 'draft',affected_classes jsonb not null default '[]',candidate_count integer not null default 0,continuity_plan_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_candidate_snapshots(id uuid primary key default gen_random_uuid(),school_id uuid not null,replacement_id uuid,candidate_staff_id uuid,availability_state text,qualification_state text,workload_snapshot jsonb not null default '{}',compatibility_snapshot jsonb not null default '{}',rank integer,created_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_continuity_plans(id uuid primary key default gen_random_uuid(),school_id uuid not null,staff_id uuid,reason_category text,starts_at timestamptz,expected_end_at timestamptz,state text not null default 'draft',affected_assignment_ids jsonb not null default '[]',handover_requirements jsonb not null default '[]',approved_by uuid,approved_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_workload_exceptions(id uuid primary key default gen_random_uuid(),school_id uuid not null,staff_id uuid,assignment_id uuid,requested_hours numeric(8,2),reason text,starts_at timestamptz,expires_at timestamptz,state text not null default 'pending',approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_qualification_exceptions(id uuid primary key default gen_random_uuid(),school_id uuid not null,staff_id uuid,assignment_id uuid,requirement_key text,reason text,starts_at timestamptz,expires_at timestamptz,state text not null default 'pending',approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_batch_runs(id uuid primary key default gen_random_uuid(),school_id uuid not null,batch_key text not null,idempotency_key text not null,state text not null default 'draft',input_json jsonb not null default '{}',result_json jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,batch_key,idempotency_key));
create table if not exists public.angelcare360_assignment_batch_items(id uuid primary key default gen_random_uuid(),school_id uuid not null,batch_run_id uuid not null references public.angelcare360_assignment_batch_runs(id),assignment_id uuid,staff_id uuid,state text not null default 'pending',failure_reason text,result_json jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_tasks(id uuid primary key default gen_random_uuid(),school_id uuid not null,assignment_id uuid,staff_id uuid,title text not null,detail text,owner_id uuid,owner_label text,due_at timestamptz,priority text not null default 'normal',state text not null default 'open',completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_notes(id uuid primary key default gen_random_uuid(),school_id uuid not null,assignment_id uuid,staff_id uuid,note text not null,created_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_history(id uuid primary key default gen_random_uuid(),school_id uuid not null,entity_type text not null,entity_id uuid,action_key text not null,label text not null,detail text,actor_id uuid,actor_label text,created_at timestamptz not null default now());
create table if not exists public.angelcare360_assignment_action_receipts(id uuid primary key default gen_random_uuid(),school_id uuid not null,action_key text not null,idempotency_key text not null,result_json jsonb not null default '{}',created_at timestamptz not null default now(),unique(school_id,action_key,idempotency_key));
create index if not exists ac360_assignment_active_idx on public.angelcare360_pedagogical_assignments(school_id,state,starts_at,ends_at);
create index if not exists ac360_assignment_conflicts_idx on public.angelcare360_assignment_conflicts(school_id,state,severity);
create index if not exists ac360_assignment_replacements_idx on public.angelcare360_assignment_replacements(school_id,state,starts_at,ends_at);
create index if not exists ac360_assignment_tasks_idx on public.angelcare360_assignment_tasks(school_id,state,due_at);
create index if not exists ac360_assignment_history_idx on public.angelcare360_assignment_history(school_id,created_at desc);
do $$ declare t text; begin foreach t in array array['angelcare360_pedagogical_assignments','angelcare360_assignment_policy_catalog','angelcare360_assignment_conflicts','angelcare360_assignment_replacements','angelcare360_assignment_candidate_snapshots','angelcare360_assignment_continuity_plans','angelcare360_assignment_workload_exceptions','angelcare360_assignment_qualification_exceptions','angelcare360_assignment_batch_runs','angelcare360_assignment_batch_items','angelcare360_assignment_tasks','angelcare360_assignment_notes','angelcare360_assignment_history','angelcare360_assignment_action_receipts'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke insert,update,delete on public.%I from anon,authenticated',t); end loop; end $$;
commit;
